window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"diamond":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"钻石"}],"examples":[{"sentence":"There are three broader lessons of Diamond’s demise at Barclays.","translation":"博达文在巴克莱的垮台，人们可以从中得出三个教训。","targetForm":"diamond","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tuesday marked the final day of the Diamond Jubilee celebrations, marking the 60th anniversary of Queen Elizabeth II's accession to the throne.","translation":"星期二是女王登基钻石庆典的最后一天，标志着伊莉莎白二世女王登基 60 周年。","targetForm":"diamond","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dismiss":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"解散"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"开除"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"解职"}],"examples":[{"sentence":"After the ceremony, the principal dismissed the students only when every parent had received the safety notice.","translation":"典礼结束后，校长等每位家长都收到安全通知，才让学生们离开。","targetForm":"dismissed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the company had to dismiss several employees during the downturn, it offered career counseling and severance pay.","translation":"尽管公司在经济下滑期间不得不开除几名员工，它仍提供了职业咨询和遣散费。","targetForm":"dismiss","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The board dismissed the director after an independent inquiry found that he had concealed a conflict of interest.","translation":"独立调查发现该主管隐瞒利益冲突后，董事会解除了他的职务。","targetForm":"dismissed","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"When the final bell rang, the teacher dismissed the class and reminded everyone to submit the assignment online.","translation":"最后一遍铃声响起时，老师让全班下课，并提醒大家在线提交作业。","targetForm":"dismissed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The minister was dismissed from office because the investigation showed that public funds had been misused.","translation":"调查显示公共资金被滥用后，这名部长被免去了职务。","targetForm":"dismissed","senseId":"source-v-3","sourceSenseId":"v-3"}]},"distinction":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"区别"}],"examples":[{"sentence":"A clear distinction must be drawn between correlation and causation in scientific research to avoid erroneous conclusions.","translation":"在科学研究中，必须明确区分相关性和因果关系，以避免错误的结论。","targetForm":"distinction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The distinction between the two philosophical doctrines lies in their fundamental assumptions about human nature.","translation":"这两种哲学学说之间的区别在于它们关于人性的基本假设。","targetForm":"distinction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Her work is of such high distinction that it has influenced a generation of scholars in the field.","translation":"她的工作具有如此卓越的声誉，以至于影响了该领域的一代学者。","targetForm":"distinction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He graduated with distinction, having maintained a grade point average that placed him in the top five percent of his class.","translation":"他以优异成绩毕业，其平均绩点使他位列班级前百分之五。","targetForm":"distinction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The subtle distinction between the two terms is often overlooked by those who are not specialists in the discipline.","translation":"这两个术语之间的细微差别常常被非该学科专家的人所忽视。","targetForm":"distinction","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dislike":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"嫌恶"}],"examples":[{"sentence":"Although Hiroko dislikes cigarette smoke, she readily goes out drinking with friends.","translation":"虽然弘子不喜欢香烟的烟雾，她却乐意和朋友出去喝酒。","targetForm":"dislikes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The only time people dislike gossip is when you gossip about them.","translation":"人们不喜欢流言蜚语的唯一时间是当你闲聊他们的事。","targetForm":"dislike","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I don't like teachers who dislike students that ask questions.","translation":"我讨厌不喜欢学生问问题的老师。","targetForm":"dislike","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dimension":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"尺寸"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"次元"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"标出尺寸"}],"examples":[{"sentence":"The architect carefully recorded every dimension of the room to ensure the custom furniture would fit perfectly.","translation":"建筑师仔细记录了房间的每一个尺寸，以确保定制的家具能够完美适配。","targetForm":"dimension","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The project's sheer dimension required a coordinated effort from multiple departments across the organization.","translation":"该项目的庞大规模需要整个组织内多个部门的协同努力。","targetForm":"dimension","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In theoretical physics, extra spatial dimensions beyond the familiar three are postulated to unify fundamental forces.","translation":"在理论物理学中，为了统一基本力，人们假设存在超出我们所熟悉的三维之外的额外空间维度。","targetForm":"dimensions","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The ethical dimension of artificial intelligence research has become a central concern for policymakers worldwide.","translation":"人工智能研究的伦理层面已成为全球政策制定者关注的核心问题。","targetForm":"dimension","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before cutting the steel beams, the engineer dimensioned each piece on the blueprint with precise measurements.","translation":"在切割钢梁之前，工程师在蓝图上用精确的测量数据标出了每一件的尺寸。","targetForm":"dimensioned","senseId":"source-v-1","sourceSenseId":"v-1"}]},"disgrace":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"耻辱"}],"examples":[{"sentence":"Because the company's negligence led to an environmental disaster, it faced public disgrace and severe legal consequences.","translation":"由于公司的疏忽导致了环境灾难，它面临公众耻辱和严重的法律后果。","targetForm":"disgrace","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The politician's involvement in the corruption scandal brought disgrace upon the entire administration, thereby eroding public confidence.","translation":"该政治家卷入腐败丑闻，给整个政府带来了耻辱，从而削弱了公众信心。","targetForm":"disgrace","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the historical injustices were exposed, the nation had to confront its past disgrace and work toward reconciliation.","translation":"当历史不公被揭露时，该国不得不面对过去的耻辱并努力实现和解。","targetForm":"disgrace","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The academic community considers plagiarism a grave disgrace, which can permanently damage a scholar's reputation.","translation":"学术界认为抄袭是一种严重的耻辱，会永久损害学者的声誉。","targetForm":"disgrace","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the team had a history of success, their unsportsmanlike conduct in the final match was a disgrace to the sport.","translation":"尽管该队有着辉煌的历史，但他们在决赛中的不道德行为是对这项运动的耻辱。","targetForm":"disgrace","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dinner":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"宴会"}],"examples":[{"sentence":"Although the dinner was scheduled for seven o'clock, many guests arrived early to network before the meal.","translation":"尽管晚宴定在七点，许多客人还是提前到达，以便在用餐前进行社交。","targetForm":"dinner","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the host prepared a traditional multi-course dinner, the international guests gained a deeper appreciation for the local cuisine.","translation":"由于主人准备了传统的多道菜晚宴，国际宾客对当地美食有了更深的了解。","targetForm":"dinner","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The charity dinner, which featured a keynote speech by a renowned philanthropist, raised over one million dollars for cancer research.","translation":"这场慈善晚宴以一位著名慈善家的主旨演讲为特色，为癌症研究筹集了超过一百万美元。","targetForm":"dinner","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"To ensure a productive discussion, the committee organized a working dinner where members could exchange ideas in a relaxed setting.","translation":"为了确保富有成效的讨论，委员会组织了一次工作晚宴，让成员在轻松的环境中交流想法。","targetForm":"dinner","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"While the formal dinner honored the retiring professor, it also served as an opportunity for alumni to reconnect with their alma mater.","translation":"这场正式晚宴在向退休教授致敬的同时，也为校友们提供了与母校重新建立联系的机会。","targetForm":"dinner","senseId":"source-n-3","sourceSenseId":"n-3"}]},"disaster":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"灾祸"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"彻底失败"}],"examples":[{"sentence":"The town developed a disaster plan so that residents would know where to find information during flooding.","translation":"城镇制定了灾害预案，使居民知道洪水期间在哪里获取信息。","targetForm":"disaster","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After the natural disaster, volunteers helped families replace documents that had been damaged by water.","translation":"自然灾害后，志愿者帮助家庭补办被水损坏的文件。","targetForm":"disaster","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The event was not a disaster, but the organisers learned that clearer signs would improve future visits.","translation":"活动并非彻底失败，但组织者认识到更清晰的标志会改善未来参观体验。","targetForm":"disaster","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Schools practised evacuation procedures so that staff could respond calmly during a local disaster.","translation":"学校演练疏散程序，使员工能在当地灾害期间冷静应对。","targetForm":"disaster","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The report explains how early warnings can reduce the disruption caused by a disaster.","translation":"报告解释了早期预警如何减少灾害造成的扰乱。","targetForm":"disaster","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dilute":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"稀释"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"冲淡"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"稀释的"}],"examples":[{"sentence":"To reduce the acidity, the chemist carefully diluted the concentrated solution with distilled water.","translation":"为了降低酸度，化学家小心地用蒸馏水稀释了浓缩溶液。","targetForm":"diluted","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The company diluted its brand value by introducing too many low-quality products under the same name.","translation":"该公司以同一品牌推出过多低质量产品，从而稀释了其品牌价值。","targetForm":"diluted","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The environmental agency found that the factory was diluting its waste before discharging it into the river.","translation":"环保机构发现该工厂在将废水排入河流之前进行了稀释。","targetForm":"diluting","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"A dilute acid is often safer to handle in the laboratory than its concentrated counterpart.","translation":"在实验室中，稀释的酸通常比其浓缩物更安全。","targetForm":"dilute","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The dilute solution of the reagent was insufficient to produce a visible reaction in the test tube.","translation":"该试剂的稀释溶液不足以在试管中产生可见的反应。","targetForm":"dilute","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"dig":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"挖"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"挖掘"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"发掘"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"挖掘"}],"examples":[{"sentence":"Although the ground was frozen, workers had to dig a trench to repair the broken water pipe.","translation":"尽管地面结冰，工人仍必须挖一条沟来修理破裂的水管。","targetForm":"dig","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To keep the building stable, engineers must dig foundations deep enough to reach solid ground.","translation":"为保持建筑稳定，工程师必须挖出足够深的地基，直到坚实土层。","targetForm":"dig","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Archaeologists dig carefully with brushes when they uncover fragile objects at an ancient site.","translation":"考古学家在古址发现脆弱物品时，会用刷子小心挖掘。","targetForm":"dig","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Because the soil was contaminated, the team had to dig out several tonnes before replacing it.","translation":"由于土壤受污染，团队必须挖出数吨土壤后再进行替换。","targetForm":"dig","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The university invited local residents to visit the dig, where students were documenting a Roman settlement.","translation":"大学邀请当地居民参观发掘现场，学生们正在那里记录一处罗马定居点。","targetForm":"dig","senseId":"source-n-1","sourceSenseId":"n-1"}]},"diary":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"日记"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"[经] 日记簿","contextReviewed":true}],"examples":[{"sentence":"She meticulously recorded her daily observations in a leather-bound diary, which she later used as a source for her memoir.","translation":"她一丝不苟地将每日观察记录在一本皮面日记本里，后来将其作为回忆录的素材。","targetForm":"diary","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Historians discovered a wartime diary that provided invaluable insights into the civilian experience during the occupation.","translation":"历史学家发现了一本战时日记，为占领期间的平民经历提供了宝贵的见解。","targetForm":"diary","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The researcher kept a detailed field diary to document the behavior of the endangered species in its natural habitat.","translation":"研究人员保存了一本详细的野外日记，记录濒危物种在其自然栖息地的行为。","targetForm":"diary","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He purchased a new desk diary to organize his appointments and deadlines for the upcoming fiscal year.","translation":"他买了一本新的台历式日记簿，用来安排即将到来的财政年度的约会和截止日期。","targetForm":"diary","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The executive's personal diary, filled with confidential notes, was accidentally left in the conference room after the meeting.","translation":"这位高管那本写满机密笔记的个人日记簿，在会议结束后被意外留在了会议室。","targetForm":"diary","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dial":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"刻度盘"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"钟面"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"拨"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"转盘"}],"examples":[{"sentence":"The technician carefully adjusted the dial on the oscilloscope to obtain a clearer waveform for analysis.","translation":"技术员小心地调整示波器上的刻度盘，以获得更清晰的波形进行分析。","targetForm":"dial","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She glanced at the elegant dial of the grandfather clock, noting that it was already half past midnight.","translation":"她瞥了一眼落地钟优雅的钟面，注意到已经是午夜十二点半了。","targetForm":"dial","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before making an international call, you must dial the country code followed by the local number.","translation":"拨打国际电话前，你必须先拨国家代码，然后再拨当地号码。","targetForm":"dial","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"He quickly dialed the emergency services when he witnessed the accident on the highway.","translation":"当他在高速公路上目睹事故时，他迅速拨打了紧急服务电话。","targetForm":"dialed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The old radio featured a large tuning dial that required a gentle touch to find the desired station.","translation":"那台旧收音机有一个大的调谐转盘，需要轻触才能找到想要的电台。","targetForm":"dial","senseId":"source-n-3","sourceSenseId":"n-3"}]},"divine":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"神的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"非凡的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"神圣的"}],"examples":[{"sentence":"Although the ancient temple was built to honor a divine being, its design also reflects human ingenuity.","translation":"尽管这座古庙是为敬奉一位神灵而建，但其设计也反映了人类的智慧。","targetForm":"divine","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the choir's performance achieved a divine perfection, the audience sat in stunned silence for several moments.","translation":"因为合唱团的表演达到了神圣的完美境界，观众在震惊的沉默中坐了好一会儿。","targetForm":"divine","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The philosopher argued that divine revelation, rather than empirical evidence, provides the ultimate source of moral truth.","translation":"这位哲学家认为，神圣启示而非经验证据，提供了道德真理的最终来源。","targetForm":"divine","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"While some view natural beauty as a divine gift, others see it as a product of evolutionary processes.","translation":"虽然有些人将自然之美视为神圣的恩赐，但其他人则将其视为进化过程的产物。","targetForm":"divine","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The poet used divine imagery to convey a sense of transcendence, which resonated deeply with readers seeking spiritual meaning.","translation":"诗人运用神圣意象来传达一种超越感，这深深引起了寻求精神意义的读者的共鸣。","targetForm":"divine","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"dialect":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"方言"}],"examples":[{"sentence":"Although Mandarin is widely used formally, many elderly villagers still speak only their local dialect.","translation":"尽管普通话在正式场合广泛使用，许多老年村民仍只说当地方言。","targetForm":"dialect","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the coastal dialect contains many borrowed words, it reflects centuries of maritime trade.","translation":"由于沿海方言包含许多外来借词，它反映了数百年的海上贸易。","targetForm":"dialect","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Linguists are documenting the dialect before it disappears, which has become a race against time.","translation":"语言学家正在记录这种方言，以免它消失，这已成为一场与时间的赛跑。","targetForm":"dialect","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While the dialect is not taught in school, it remains a vibrant part of the community's cultural heritage.","translation":"尽管学校不教授这种方言，它仍是社区文化遗产中充满活力的一部分。","targetForm":"dialect","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Preserving a dialect can strengthen social ties by giving speakers a shared sense of belonging.","translation":"保护方言能通过给予使用者共同归属感来加强社会联系。","targetForm":"dialect","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dive":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"潜水"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"跳水"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"俯冲"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"猛冲"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"把...突然伸入"}],"examples":[{"sentence":"The scuba instructor led a group of beginners on their first open-water dive near the coral reef.","translation":"潜水教练带领一群初学者在珊瑚礁附近进行了他们的首次开放水域潜水。","targetForm":"dive","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Her graceful dive from the ten-meter platform earned a perfect score from every judge.","translation":"她从十米跳台上优雅的一跳赢得了每位裁判的满分。","targetForm":"dive","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The peregrine falcon dives at incredible speeds to catch its prey in mid-air.","translation":"游隼以惊人的速度俯冲，在半空中捕捉猎物。","targetForm":"dives","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When the fire alarm sounded, everyone dived for the nearest emergency exit.","translation":"火警响起时，所有人都冲向最近的紧急出口。","targetForm":"dived","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"She dived her hand into the icy water to retrieve the fallen keys.","translation":"她把手突然伸入冰冷的水中，去捞掉落的钥匙。","targetForm":"dived","senseId":"source-v-4","sourceSenseId":"v-4"}]},"director":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"董事"}],"examples":[{"sentence":"Finally, some object that bankers dominate the boards of directors of the regional Reserve Banks, making it seem that the foxes are guarding the henhouse.","translation":"最后，一些人反对银行家把持了地区联储银行董事会，这就好像是让狐狸看守鸡窝。","targetForm":"directors","senseId":"source-n-3","sourceSenseId":"n-3"}]},"disguise":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"假面目"}],"examples":[{"sentence":"A thin disguise of politeness often conceals deep-seated prejudice in professional settings, which can hinder genuine collaboration and innovation.","translation":"在职业环境中，一层薄薄的礼貌伪装往往掩盖着根深蒂固的偏见，这会阻碍真正的合作与创新。","targetForm":"disguise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Beneath a disguise of generosity, the policy actually served to concentrate power among a small elite, which ultimately undermined democratic processes.","translation":"在慷慨的伪装下，该政策实际上是为了将权力集中在一小部分精英手中，这最终破坏了民主进程。","targetForm":"disguise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The historian noted that many authoritarian regimes use the disguise of national security to suppress dissent, while simultaneously eroding civil liberties.","translation":"这位历史学家指出，许多威权政权利用国家安全的伪装来压制异议，同时侵蚀公民自由。","targetForm":"disguise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the proposal came in the disguise of environmental protection, its primary goal was to secure commercial advantages for a few corporations.","translation":"尽管该提案以环境保护为伪装，但其主要目标是为少数公司获取商业利益。","targetForm":"disguise","senseId":"source-n-1","sourceSenseId":"n-1"}]},"disregard":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"漠视"}],"examples":[{"sentence":"The official's blatant disregard for ethical standards eroded public trust in the entire institution, which took years to rebuild.","translation":"该官员对道德标准的公然漠视侵蚀了公众对整个机构的信任，这花了多年时间才得以重建。","targetForm":"disregard","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because of a widespread disregard for intellectual property rights, many innovators are reluctant to share their discoveries, thereby slowing technological progress.","translation":"由于对知识产权的普遍漠视，许多创新者不愿分享他们的发现，从而减缓了技术进步。","targetForm":"disregard","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The company's persistent disregard for safety regulations eventually led to a catastrophic accident, which could have been prevented through stricter oversight.","translation":"该公司对安全法规的持续漠视最终导致了一场灾难性事故，这本可以通过更严格的监督来避免。","targetForm":"disregard","senseId":"source-n-2","sourceSenseId":"n-2"}]},"dissolve":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"溶解"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"解散"}],"examples":[{"sentence":"The chemist carefully dissolved the crystalline compound in a heated solvent to initiate the reaction.","translation":"化学家小心地将结晶化合物溶解在加热的溶剂中以启动反应。","targetForm":"dissolved","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When the tablet dissolves in water, it releases a gas that indicates the completion of the process.","translation":"当药片在水中溶解时，会释放出一种气体，表明过程已完成。","targetForm":"dissolves","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The committee voted to dissolve the organization after it had fulfilled its original mandate.","translation":"委员会投票决定在该组织完成其最初使命后将其解散。","targetForm":"dissolve","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The prime minister requested the monarch to dissolve parliament ahead of the scheduled elections.","translation":"首相请求君主在预定选举前解散议会。","targetForm":"dissolve","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Over time, the sugar dissolved completely into the tea, leaving no visible granules behind.","translation":"随着时间的推移，糖完全溶解在茶中，没有留下可见的颗粒。","targetForm":"dissolved","senseId":"source-v-1","sourceSenseId":"v-1"}]},"disc":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"唱片"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"圆盘"}],"examples":[{"sentence":"Although streaming is popular, many collectors still value the tactile experience of handling a vinyl disc.","translation":"尽管流媒体很流行，许多收藏家仍然珍视处理黑胶唱片的触觉体验。","targetForm":"disc","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the compact disc offered superior durability, it became the preferred medium for data storage in the 1990s.","translation":"由于光盘提供了卓越的耐用性，它在20世纪90年代成为数据存储的首选介质。","targetForm":"disc","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When the hard disc fails, critical data can be lost unless a backup has been made.","translation":"当硬盘发生故障时，除非已进行备份，否则关键数据可能会丢失。","targetForm":"disc","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The technician inserted the installation disc into the drive, thereby initiating the software setup process.","translation":"技术人员将安装光盘插入驱动器，从而启动了软件安装过程。","targetForm":"disc","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The archaeologist carefully cleaned the ancient stone disc, which was carved with mysterious symbols.","translation":"考古学家小心地清理了那块刻有神秘符号的古代石盘。","targetForm":"disc","senseId":"source-n-1","sourceSenseId":"n-1"}]},"discovery":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"发现"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"被发现的事物"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"（法律）证据开示；要求告知","contextReviewed":true},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"发觉；领悟","contextReviewed":true}],"examples":[{"sentence":"The discovery of a new species may attract attention, but protecting its habitat requires long-term funding.","translation":"新物种的发现或许会吸引关注，但保护其栖息地需要长期资金。","targetForm":"discovery","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The museum's most valuable discovery, a bronze seal bearing an unknown emblem, was found beneath the ruined wall.","translation":"博物馆最有价值的发现是一枚刻有未知徽记的青铜印章，它在残墙下被发现。","targetForm":"discovery","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"During discovery, the company was required to disclose internal emails relevant to the lawsuit.","translation":"在证据开示阶段，公司被要求披露与该诉讼有关的内部邮件。","targetForm":"discovery","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Her discovery that the figures had been copied from an outdated report changed the direction of the investigation.","translation":"她发觉这些数字是从一份过时报告中抄来的，这改变了调查的方向。","targetForm":"discovery","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Although the archaeological discovery was accidental, it provided historians with evidence of an earlier settlement.","translation":"尽管这项考古发现纯属偶然，它仍为历史学家提供了更早聚落存在的证据。","targetForm":"discovery","senseId":"source-n-1","sourceSenseId":"n-1"}]},"digest":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"文摘"}],"examples":[{"sentence":"Although the weekly digest of industry news saves professionals considerable time, it cannot replace the depth of analysis found in full-length reports.","translation":"尽管每周的行业新闻文摘为专业人士节省了大量时间，但它无法取代完整报告中分析的深度。","targetForm":"digest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"To help students digest the complex theories of quantum mechanics, the textbook includes a digest of each chapter that summarizes the essential principles.","translation":"为了帮助学生理解复杂的量子力学理论，教科书每章都包含一个摘要，总结基本原理。","targetForm":"digest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the research paper was dense with technical jargon, the professor prepared a concise digest that highlighted the key findings for a broader audience.","translation":"由于这篇研究论文充满了技术术语，教授准备了一份简明的摘要，为更广泛的读者突出了关键发现。","targetForm":"digest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The human digestive system requires several hours to fully digest a meal rich in fiber, which is why nutritionists recommend eating slowly and mindfully.","translation":"人体消化系统需要几个小时才能完全消化富含纤维的一餐，这就是营养学家建议细嚼慢咽、专心进食的原因。","targetForm":"digest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After attending the intensive workshop, participants were given a digest of the main strategies so that they could apply the concepts in their own workplaces.","translation":"参加完密集研讨会后，与会者收到了一份主要策略的摘要，以便他们能在自己的工作场所应用这些概念。","targetForm":"digest","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dignity":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"尊严"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"高贵"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"高位；显要职位","contextReviewed":true}],"examples":[{"sentence":"Respecting the dignity of patients means explaining treatment choices in language they can genuinely understand.","translation":"尊重患者的尊严，意味着要用他们真正能理解的语言解释治疗选择。","targetForm":"dignity","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Even after the hostile interview, she answered with a quiet dignity that made the attack seem petty.","translation":"即使经历了充满敌意的采访，她仍以从容的庄严作答，使攻击显得卑微。","targetForm":"dignity","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The ambassador accepted the dignity only after confirming that the appointment would not compromise her independence.","translation":"这位大使只有在确认该显要职位不会损害自己的独立性后才接受任命。","targetForm":"dignity","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Policies that force older people to surrender privacy can undermine their dignity, however efficient the system appears.","translation":"迫使老年人放弃隐私的政策可能损害他们的尊严，无论制度表面上多么高效。","targetForm":"dignity","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The ceremony retained its dignity because the speakers avoided exaggeration and acknowledged the community's losses honestly.","translation":"这场仪式之所以保持庄严，是因为发言者避免夸张，并真诚承认了社区遭受的损失。","targetForm":"dignity","senseId":"source-n-2","sourceSenseId":"n-2"}]},"dilemma":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"(进退两难的)窘境"}],"examples":[{"sentence":"The editor faced a dilemma because publishing the report quickly might compromise its accuracy.","translation":"编辑面临两难困境，因为仓促发表这篇报道可能损害其准确性。","targetForm":"dilemma","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"For many graduates, the dilemma is whether to accept secure employment or pursue uncertain research.","translation":"对许多毕业生来说，两难之处在于接受稳定工作，还是投身前景未明的研究。","targetForm":"dilemma","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The ethical dilemma became sharper when the committee learned that both options would affect vulnerable residents.","translation":"委员会得知两种方案都会影响弱势居民后，这一伦理困境变得更加尖锐。","targetForm":"dilemma","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the dilemma appeared personal, its solution required clear rules from the whole organisation.","translation":"尽管这个两难问题看似是个人的，但解决它需要整个机构制定明确规则。","targetForm":"dilemma","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Faced with a funding dilemma, the museum postponed expansion rather than reduce its education programme.","translation":"面对资金上的两难，博物馆选择推迟扩建，而没有削减教育项目。","targetForm":"dilemma","senseId":"source-n-2","sourceSenseId":"n-2"}]},"dissipate":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"消散"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"驱散"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"浪费"}],"examples":[{"sentence":"The morning mist began to dissipate as the sun rose over the valley.","translation":"当太阳升起在山谷上空时，晨雾开始消散。","targetForm":"dissipate","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The ventilation system helps dissipate heat generated by the industrial machinery.","translation":"通风系统有助于驱散工业机械产生的热量。","targetForm":"dissipate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Over time, the initial enthusiasm for the project dissipated due to a lack of funding.","translation":"随着时间的推移，由于缺乏资金，对该项目最初的热情消散了。","targetForm":"dissipated","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"He dissipated his inheritance on extravagant purchases and unwise investments.","translation":"他将遗产浪费在奢侈的消费和不明智的投资上。","targetForm":"dissipated","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The young heir dissipated his fortune through years of reckless living and gambling.","translation":"年轻的继承人通过多年的放荡生活和赌博挥霍了他的财富。","targetForm":"dissipated","senseId":"source-v-3","sourceSenseId":"v-3"}]},"diffuse":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"传播"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"散播"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"弥漫的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"散开的"}],"examples":[{"sentence":"The organization diffuses vital health information through community workshops, ensuring that even remote villages receive accurate guidance.","translation":"该组织通过社区研讨会传播重要的健康信息，确保即使偏远村庄也能获得准确的指导。","targetForm":"diffuses","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Technological innovations often diffuse gradually across industries, as early adopters demonstrate their benefits before widespread implementation occurs.","translation":"技术创新通常逐渐传播到各个行业，因为早期采用者在广泛实施之前展示了其益处。","targetForm":"diffuse","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The light in the gallery was softly diffused by frosted glass panels, creating an even illumination that enhanced the artwork.","translation":"画廊里的光线被磨砂玻璃板柔和地散射开来，营造出均匀的照明，增强了艺术品的展示效果。","targetForm":"diffused","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A diffuse glow emanated from the horizon at dawn, gradually revealing the contours of the sleeping city.","translation":"黎明时分，地平线上散发出弥漫的光芒，逐渐显露出沉睡城市的轮廓。","targetForm":"diffuse","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The patient’s symptoms were diffuse and nonspecific, which complicated the diagnostic process for the medical team.","translation":"患者的症状是弥漫性的且非特异性，这使医疗团队的诊断过程变得复杂。","targetForm":"diffuse","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"disastrous":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"损失惨重的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"悲伤的"}],"examples":[{"sentence":"The decision to ignore the flood warnings proved disastrous when thousands of homes were damaged overnight.","translation":"无视洪水预警的决定造成灾难性后果，一夜之间数千所房屋受损。","targetForm":"disastrous","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the product launch seemed well funded, a disastrous supply failure left shops with empty shelves.","translation":"尽管产品发布看似资金充足，一次灾难性的供应故障仍使商店货架空空。","targetForm":"disastrous","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The community held a quiet meeting after the disastrous fire, listening to families who had lost their homes.","translation":"那场令人痛心的大火后，社区举行了一次安静的会议，倾听失去家园的家庭发言。","targetForm":"disastrous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Without careful testing, a seemingly minor coding error can have disastrous consequences for a public service.","translation":"如果没有仔细测试，一个看似轻微的编码错误可能会给公共服务带来灾难性后果。","targetForm":"disastrous","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The journalist described the accident as disastrous, yet avoided exploiting the grief of those directly affected.","translation":"记者把这场事故描述为惨痛的灾难，却避免利用直接受害者的悲伤来博取关注。","targetForm":"disastrous","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"different":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"不同的"}],"examples":[{"sentence":"The two men held very different views about how best to guarantee Israel’s security, and it is worth recapitulating their respective arguments.","translation":"两人对如何更好地保证以色列的安全的问题意见强烈相左，在这里有必要概括一下他们各自的观点。","targetForm":"different","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"die":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"死亡"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"消逝"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"平息"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"渴望"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"骰子"}],"examples":[{"sentence":"Without prompt treatment, patients with severe infections may die from complications that modern medicine can often prevent.","translation":"如果没有及时治疗，严重感染患者可能死于现代医学通常能够预防的并发症。","targetForm":"die","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When a language dies, it takes with it ways of describing the world that may never be recovered.","translation":"当一种语言消亡时，它也带走了可能永远无法恢复的描述世界的方式。","targetForm":"dies","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"After the announcement, the applause died away and the audience waited for the speaker to continue.","translation":"宣布之后，掌声逐渐平息，观众等待演讲者继续。","targetForm":"died","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"She was dying to read the final chapter, but she waited until the train journey home.","translation":"她迫不及待想读最后一章，却忍到坐火车回家的路上才读。","targetForm":"dying","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"A single die was missing from the board game, so the children used a phone application instead.","translation":"棋盘游戏少了一枚骰子，因此孩子们改用手机应用程序。","targetForm":"die","senseId":"source-n-1","sourceSenseId":"n-1"}]},"discourage":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"阻碍"}],"examples":[{"sentence":"Public policy that discriminates against and discourages vital innovations in food production is not policy that has the public’s interest at heart.","translation":"由此可见，那些敌视并压制在食品生产方面的重要革新的公共政策并不是真心维护民众利益的政策。","targetForm":"discourages","senseId":"source-v-2","sourceSenseId":"v-2"}]},"disappoint":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使失望"}],"examples":[{"sentence":"If this is the reason, it is disappointing, given how much work has gone into developing both the regulatory-led and the court-led restructuring mechanisms.","translation":"如果这才是原因的话，着实令人失望，因为制定监管领衔和法庭领衔的重组机制都已经做了大量功课。","targetForm":"disappointing","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"I was really disappointed when I found out that I hadn't passed the exam.","translation":"当我发现我没通过测验时我实在是太沮丧了。","targetForm":"disappointed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"district":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"地段","contextReviewed":true},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"区域"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"地区","contextReviewed":true}],"examples":[{"sentence":"Because the historic district is legally protected, every renovation must preserve the original street pattern and building materials.","translation":"由于历史街区受法律保护，每一次翻新都必须保留原有街道格局和建筑材料。","targetForm":"district","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The school district introduced a new reading programme after teachers reported that many pupils needed earlier support.","translation":"教师报告许多学生需要更早支持后，学区推出了一项新的阅读计划。","targetForm":"district","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the financial district is known for tall offices, it also contains small public gardens that remain quiet at lunchtime.","translation":"尽管金融区以高楼办公楼闻名，它也有一些午餐时间仍很安静的小型公共花园。","targetForm":"district","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"When the shopping district became pedestrian-only, local cafés reported more visitors who were willing to stay longer.","translation":"当购物区变成步行区后，当地咖啡馆报告说愿意停留更久的游客更多了。","targetForm":"district","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The hospital serves a rural district where long travel distances can delay treatment for patients with limited mobility.","translation":"这家医院服务于一个农村地区，漫长路程可能延误行动不便患者的治疗。","targetForm":"district","senseId":"source-n-3","sourceSenseId":"n-3"}]},"divert":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"转移"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使欢娱"}],"examples":[{"sentence":"The construction project diverted the river's flow through a temporary channel to protect the foundation of the new bridge.","translation":"建设项目将河水分流通过一条临时渠道，以保护新桥的地基。","targetForm":"diverted","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The government decided to divert funds from the military budget to support public health initiatives during the crisis.","translation":"政府决定从军事预算中转移资金，以支持危机期间的公共卫生倡议。","targetForm":"divert","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Air traffic controllers had to divert several flights to alternate airports because of severe thunderstorms over the region.","translation":"由于该地区上空有严重雷暴，空中交通管制员不得不将几个航班改道至备用机场。","targetForm":"divert","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The company introduced a new recreational area to divert employees from the stress of their daily responsibilities.","translation":"公司引入了一个新的休闲区，以使员工从日常职责的压力中转移注意力。","targetForm":"divert","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The magician's clever tricks diverted the audience while his assistant prepared the next illusion behind the curtain.","translation":"魔术师巧妙的戏法使观众愉悦，而他的助手则在幕后准备下一个幻象。","targetForm":"diverted","senseId":"source-v-2","sourceSenseId":"v-2"}]},"dizzy":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"晕眩的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"眼花缭乱的"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使晕眩"}],"examples":[{"sentence":"After standing up too quickly, she felt dizzy and had to steady herself against the wall.","translation":"她站起来太快，感到头晕目眩，不得不靠在墙上稳住自己。","targetForm":"dizzy","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The patient complained of feeling dizzy whenever he turned his head suddenly.","translation":"病人抱怨每当突然转头时就会感到头晕。","targetForm":"dizzy","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The dizzy pace of technological change leaves many people struggling to keep up.","translation":"技术变革的飞快速度让许多人难以跟上。","targetForm":"dizzy","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"From the top of the skyscraper, the dizzy height made him grip the railing tightly.","translation":"从摩天大楼顶部望去，令人眩晕的高度让他紧紧抓住栏杆。","targetForm":"dizzy","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The rapid spinning of the carnival ride dizzied the children, who laughed with delight.","translation":"嘉年华游乐设施的快速旋转使孩子们感到眩晕，他们高兴地笑了起来。","targetForm":"dizzied","senseId":"source-v-1","sourceSenseId":"v-1"}]},"distance":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"距离"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"远方"}],"examples":[{"sentence":"The researchers collaborated seamlessly via video conferencing, despite the distance that separated their laboratories on different continents.","translation":"尽管距离将位于不同大陆的实验室隔开，研究人员通过视频会议实现了无缝协作。","targetForm":"distance","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"From a distance, the mountain appeared serene, yet its slopes concealed treacherous terrain that challenged even experienced climbers.","translation":"从远处看，这座山显得宁静，但其山坡隐藏着危险的地形，甚至对经验丰富的登山者也是挑战。","targetForm":"distance","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the distance between the two cities is considerable, the new high-speed rail line has effectively reduced travel time.","translation":"尽管两座城市之间的距离遥远，但新的高铁线路有效缩短了旅行时间。","targetForm":"distance","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the perceived distance between social classes can hinder effective communication, policymakers must address this issue to promote social cohesion.","translation":"由于社会阶层之间感知到的距离会阻碍有效沟通，政策制定者必须解决这一问题以促进社会凝聚力。","targetForm":"distance","senseId":"source-n-1","sourceSenseId":"n-1"}]},"diameter":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"直径"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"[医] 直经","contextReviewed":true}],"examples":[{"sentence":"The diameter of the ancient tree trunk measured over two meters, indicating its great age.","translation":"这棵古树树干的直径超过两米，表明其年代久远。","targetForm":"diameter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Engineers calculated the pipe's diameter to ensure sufficient water flow for the entire building.","translation":"工程师计算了管道的直径，以确保整栋建筑有足够的水流量。","targetForm":"diameter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The diameter of the lens directly affects the amount of light that enters the camera.","translation":"镜头的直径直接影响进入相机的光量。","targetForm":"diameter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In geometry class, we learned that the diameter is twice the length of the radius.","translation":"在几何课上，我们学到直径是半径长度的两倍。","targetForm":"diameter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The surgeon measured the diameter of the artery before selecting the appropriate stent size.","translation":"外科医生测量了动脉的直径，然后选择了合适的支架尺寸。","targetForm":"diameter","senseId":"source-n-2","sourceSenseId":"n-2"}]},"disturbance":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"干扰","contextReviewed":true},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"扰乱"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"不安"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"忧虑"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"[化] 扰动","contextReviewed":true}],"examples":[{"sentence":"The loud disturbance from the construction site made it impossible to concentrate on the lecture.","translation":"建筑工地传来的巨大干扰使人无法集中精力听课。","targetForm":"disturbance","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Any disturbance to the ecosystem, such as pollution, can have long-lasting effects on biodiversity.","translation":"对生态系统的任何扰乱，如污染，都可能对生物多样性产生长期影响。","targetForm":"disturbance","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The patient experienced severe emotional disturbance after the traumatic event, requiring professional counseling.","translation":"患者在创伤事件后经历了严重的不安情绪，需要专业咨询。","targetForm":"disturbance","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Her constant disturbance about the upcoming exam led to sleepless nights and decreased appetite.","translation":"她对即将到来的考试持续忧虑，导致失眠和食欲下降。","targetForm":"disturbance","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The chemical disturbance in the reactor caused an unexpected temperature spike, alarming the operators.","translation":"反应器中的化学扰动导致温度意外飙升，使操作员警觉。","targetForm":"disturbance","senseId":"source-n-4","sourceSenseId":"n-4"}]},"dictionary":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"词典"}],"examples":[{"sentence":"A comprehensive dictionary, which includes etymologies and usage notes, is an indispensable tool for advanced language learners.","translation":"一本包含词源和用法说明的综合词典是高级语言学习者不可或缺的工具。","targetForm":"dictionary","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because a bilingual dictionary bridges two languages, it must account for cultural nuances that affect word meaning.","translation":"由于双语词典连接两种语言，它必须考虑影响词义的文化细微差别。","targetForm":"dictionary","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The historical dictionary project, which documents the evolution of vocabulary, reveals how societal changes shape language.","translation":"记录词汇演变的历史词典项目揭示了社会变迁如何塑造语言。","targetForm":"dictionary","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although online dictionaries are easily accessible, a printed dictionary can provide a distraction-free learning experience.","translation":"尽管在线词典易于访问，但印刷版词典可以提供无干扰的学习体验。","targetForm":"dictionaries","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When compiling a dictionary, lexicographers must carefully analyze vast corpora to determine accurate definitions.","translation":"在编纂词典时，词典编纂者必须仔细分析大量语料库以确定准确的定义。","targetForm":"dictionary","senseId":"source-n-2","sourceSenseId":"n-2"}]},"difficult":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"困难的"}],"examples":[{"sentence":"In the meantime, the Democrats should make that as difficult as possible and focus squarely on taking back the House next year.","translation":"与此同时，民主党人应尽可能给特朗普制造困难，并将明年夺回众议院席位作为工作重点。","targetForm":"difficult","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"This pattern can be only partly repeated in the eurozone, where both debt socialization and a return to normal risk assessment appear more difficult.","translation":"这一模式在欧洲只能部分被复制，因为在欧洲，债务社会化和正常风险评估的回归都要更加困难。","targetForm":"difficult","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"difficulty":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"困难"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"难点"}],"examples":[{"sentence":"Although the task presented considerable difficulty, the team completed it by dividing the work into clear stages.","translation":"尽管任务存在相当大的困难，团队仍通过把工作分为清晰阶段完成了它。","targetForm":"difficulty","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the instructions were ambiguous, many students had difficulty understanding what the assignment required.","translation":"由于说明含糊不清，许多学生难以理解作业要求。","targetForm":"difficulty","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The main difficulty of the experiment was keeping temperature constant while measurements were being taken.","translation":"该实验的主要难点是在测量进行时保持温度恒定。","targetForm":"difficulty","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"While learning a language involves initial difficulty, regular practice gradually makes unfamiliar patterns more manageable.","translation":"虽然学习语言一开始有困难，规律练习会逐渐使陌生模式更容易掌握。","targetForm":"difficulty","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If the difficulty seems overwhelming, identifying the first practical step can prevent the problem from becoming paralysing.","translation":"如果困难看似难以承受，找出第一个实际步骤能防止问题变得令人无从下手。","targetForm":"difficulty","senseId":"source-n-1","sourceSenseId":"n-1"}]},"directly":{"senseGroups":[{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"直接地"}],"examples":[{"sentence":"Such action must not only aim to protect shark populations directly; it must also address major threats to sharks, such as illegal trade, bycatch, and overfishing.","translation":"此类行动不仅要致力于鲨鱼种群的直接保护；还必须消除非法贸易、误捕以及过度捕捞等鲨鱼所面临的主要威胁。","targetForm":"directly","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"Government investment in infrastructure, both alone and in partnership with private firms, will also directly benefit growth and attract larger inflows of foreign investment.","translation":"政府基础设施投资 — — 不管是独资还是与私人企业合资 — — 也能直接有利于增长，吸引更多的外国投资流入。","targetForm":"directly","senseId":"source-adv-2","sourceSenseId":"adv-2"}]},"distinct":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"显著的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"不同的"}],"examples":[{"sentence":"BERKELEY – Across the globe, the debate over fiscal consolidation has the distinct sound of two sides talking past one another.","translation":"伯克利 — — 眼下，全世界都在争论要不要巩固财政，其中有两种声音非常突出，但它们相互之间简直是鸡同鸭讲。","targetForm":"distinct","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Europe, with its four distinct seasons, is the most suitable environment for the human race to live in.","translation":"欧洲四季分明，是最适合人类居住的地区。","targetForm":"distinct","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"dictate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"听写"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"命令"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"命令"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"口述"}],"examples":[{"sentence":"The teacher dictated a short paragraph so that students could practise accurate spelling and punctuation.","translation":"老师口述了一段短文，让学生练习准确拼写和标点。","targetForm":"dictated","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although market trends matter, they should not dictate every long-term decision a company makes.","translation":"尽管市场趋势很重要，它们不应决定公司作出的每一项长期决策。","targetForm":"dictate","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"When safety rules dictate a delay, the team explains the reason rather than rushing the work.","translation":"当安全规则要求延迟时，团队解释原因而不是仓促工作。","targetForm":"dictate","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The manager issued a clear dictate that confidential records must remain inside the office.","translation":"经理下达了一项明确命令：机密记录必须留在办公室内。","targetForm":"dictate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the lecturer dictated her notes slowly, the assistant could record every technical term correctly.","translation":"由于讲师缓慢口述笔记，助理能够正确记录每个技术术语。","targetForm":"dictated","senseId":"source-v-2","sourceSenseId":"v-2"}]},"discriminate":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"差别待遇"}],"examples":[{"sentence":"Public policy that discriminates against and discourages vital innovations in food production is not policy that has the public’s interest at heart.","translation":"由此可见，那些敌视并压制在食品生产方面的重要革新的公共政策并不是真心维护民众利益的政策。","targetForm":"discriminates","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"In other words, people should not be discriminated against on the grounds of having or having had leprosy – or, indeed, any disease.","translation":"换言之，人们不应因为患有或曾经患有麻风病或者其他任何疾病而遭受他人的歧视。","targetForm":"discriminated","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Discriminating against people because of their race is a mistake.","translation":"因为人的种族而歧视他们是一种错误。","targetForm":"discriminating","senseId":"source-v-2","sourceSenseId":"v-2"}]},"distribute":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"分配"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"分发"}],"examples":[{"sentence":"When governments distribute resources based on transparent criteria, public trust in the system tends to increase significantly.","translation":"当政府根据透明的标准分配资源时，公众对该系统的信任往往会显着增加。","targetForm":"distribute","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To ensure equitable access, the organization decided to distribute the educational materials through local libraries and community centers.","translation":"为了确保公平获取，该组织决定通过当地图书馆和社区中心分发教育材料。","targetForm":"distribute","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Because the charity failed to distribute the donations efficiently, many families in need did not receive the promised aid.","translation":"由于慈善机构未能有效分发捐赠物资，许多有需要的家庭没有收到承诺的援助。","targetForm":"distribute","senseId":"source-v-3","sourceSenseId":"v-3"}]},"distinguish":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"区别"}],"examples":[{"sentence":"To distinguish fact from fiction, readers should evaluate sources rather than accept claims at face value.","translation":"为了区分事实与虚构，读者应该评估信息来源，而不是只看表面就接受说法。","targetForm":"distinguish","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the two concepts are often conflated, it is essential to distinguish between equality and equity in policy discussions.","translation":"由于这两个概念经常被混淆，在政策讨论中区分平等与公平至关重要。","targetForm":"distinguish","senseId":"source-v-1","sourceSenseId":"v-1"}]},"disrupt":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"中断的"}],"examples":[{"sentence":"Software development as an industry is very adaptable, so it's unclear whether AI will significantly disrupt the programming job market.","translation":"软体开发业的适应力很强，因此 AI 是否会对程式设计的就业市场造成重大冲击，目前仍不明朗。","targetForm":"disrupt","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Don't eat too much and disrupt the stomach's normal digestion process.","translation":"不要因为吃得太多而扰乱胃的正常消化。","targetForm":"disrupt","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"direction":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"方向"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"趋势"}],"examples":[{"sentence":"While depreciation would never be eurozone officials’ stated policy, it currently looks like all roads lead in that direction.","translation":"贬值永远不会是欧元区官员直言不讳的选择，但从目前来看，这正是欧洲在走的路。","targetForm":"direction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Unfortunately, however, while the direction of Africa’s trade may be changing, its composition – raw-material exports and manufactured imports – is not.","translation":"然而不幸的是，虽然非洲贸易的整体风向已经转变，但其内部构成 — — 原材料出口和制成品进口 — — 却没有改变。","targetForm":"direction","senseId":"source-n-3","sourceSenseId":"n-3"}]},"differentiate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"区别"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"区分"}],"examples":[{"sentence":"Effective branding helps a company differentiate its products in a crowded market, thereby attracting loyal customers.","translation":"有效的品牌塑造有助于公司在拥挤的市场中区分其产品，从而吸引忠实的客户。","targetForm":"differentiate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The new diagnostic tool can differentiate malignant tumors from benign ones with high accuracy, which reduces unnecessary surgeries.","translation":"这种新的诊断工具能够高精度地区分恶性肿瘤和良性肿瘤，从而减少了不必要的手术。","targetForm":"differentiate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although the twins looked identical, their teachers could differentiate them by their distinct learning styles.","translation":"尽管这对双胞胎看起来一模一样，但他们的老师可以通过他们不同的学习风格来区分他们。","targetForm":"differentiate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because the two species share a common ancestor, it is often difficult to differentiate them based solely on morphological traits.","translation":"因为这两个物种有共同的祖先，所以通常很难仅凭形态特征来区分它们。","targetForm":"differentiate","senseId":"source-v-2","sourceSenseId":"v-2"}]},"distort":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"扭曲"}],"examples":[{"sentence":"First, countries should dismantle protectionist measures they have in place, and make a firm commitment not to implement policies that distort global markets.","translation":"首先，各国应该取消目前的保护主义措施，并切实承诺不实施扭曲全球市场的政策。","targetForm":"distort","senseId":"source-v-1","sourceSenseId":"v-1"}]},"dirty":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"肮脏的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"卑鄙的"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"弄脏"}],"examples":[{"sentence":"The volunteers cleaned the dirty riverbank before the festival, removing plastic that had accumulated after recent floods.","translation":"志愿者在节日前清理了肮脏河岸，移除了近期洪水后积累的塑料。","targetForm":"dirty","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the campaign denied using dirty tactics, leaked messages showed attempts to mislead voters about the opponent.","translation":"尽管竞选活动否认使用卑鄙手段，泄露信息显示有人试图就对手误导选民。","targetForm":"dirty","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Mud from the construction site dirtied the pavement, so the contractor installed temporary washing points for vehicles.","translation":"施工现场的泥土弄脏了人行道，因此承包商为车辆安装临时清洗点。","targetForm":"dirtied","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The laboratory notes were kept separate from dirty equipment, which reduced the risk of contaminating the written record.","translation":"实验室笔记与脏设备分开存放，降低了书面记录受污染的风险。","targetForm":"dirty","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The disclosure exposed a dirty deal in which private gain had been placed ahead of the community's stated interests.","translation":"披露揭露了一项不正当交易，其中私人利益被置于社区既定利益之上。","targetForm":"dirty","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"disease":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"疾病"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"弊病"}],"examples":[{"sentence":"The report examines how disease can affect access to education when families face long journeys for routine services.","translation":"报告考察了当家庭必须长途前往常规服务地点时，疾病如何影响受教育机会。","targetForm":"disease","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the study tracked one disease, its findings may not apply automatically to every public health setting.","translation":"尽管研究追踪的是一种疾病，它的发现未必能自动适用于每一种公共卫生环境。","targetForm":"disease","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The museum's display explains how researchers use historical records to understand changes in disease over time.","translation":"博物馆展览解释了研究人员如何利用历史记录来理解疾病随时间发生的变化。","targetForm":"disease","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The author called short-term thinking a disease of modern planning because it ignores consequences that emerge later.","translation":"作者把短视称作现代规划的弊病，因为它忽视了后来才显现的后果。","targetForm":"disease","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Rather than treat delay as an unavoidable disease of public administration, the council mapped each approval step.","translation":"市政部门没有把拖延视为公共管理不可避免的弊病，而是梳理了每一步审批流程。","targetForm":"disease","senseId":"source-n-2","sourceSenseId":"n-2"}]},"direct":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"直接的"}],"examples":[{"sentence":"The UN-REDD Program, launched in 2008, currently supports 44 developing countries, with 16 countries receiving direct financial and technical support.","translation":"2008年实行的UN-REDD计划目前支持着44个发展中国家，其中16国受到了直接金融和技术支持。","targetForm":"direct","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"disclose":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"公开","contextReviewed":true},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"透露"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"揭露"}],"examples":[{"sentence":"The company disclosed the error before the report was published, which allowed readers to see how the figures had been corrected.","translation":"公司在报告发表前披露了错误，使读者能看到数字如何被更正。","targetForm":"disclosed","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Although the witness was willing to help, she did not disclose the identity of anyone who might face retaliation.","translation":"尽管证人愿意协助，她没有透露任何可能遭到报复者的身份。","targetForm":"disclose","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The contract requires suppliers to disclose relevant conflicts of interest before receiving public funds.","translation":"合同要求供应商在获得公共资金前披露相关利益冲突。","targetForm":"disclose","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The investigation disclosed a pattern of ignored warnings, which explained why the problem had become more serious over time.","translation":"调查揭露了警告被忽视的模式，解释了为何问题随时间变得更严重。","targetForm":"disclosed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Before publication, the editors disclosed their method of selecting sources so that readers could assess its limitations.","translation":"发表前，编辑公开了选择来源的方法，使读者能评估其局限。","targetForm":"disclosed","senseId":"source-v-4","sourceSenseId":"v-4"}]},"diverse":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"不同的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"变化多的"}],"examples":[{"sentence":"Europe deserves to prove that it is a real community, one diverse, democratic, spiritual, free, and prosperous.","translation":"欧洲应该证明自己是一个真正的社会，一个多元、民主、高尚、自由和繁荣的社会。","targetForm":"diverse","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Both examples show that Europe, like the US, is vulnerable to the politics of division, as our societies become more ethnically diverse.","translation":"这两个例子都显示出随着我们的社会在种族上越来越多元化，欧洲也无法克服随之诱发的政治分裂现象，正如美国一样。","targetForm":"diverse","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the city is known for its diverse culinary scene, it lacks affordable housing for low-income residents.","translation":"尽管这座城市以其多样化的美食闻名，但它缺乏面向低收入居民的负担得起的住房。","targetForm":"diverse","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"dirt":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"污垢"}],"examples":[{"sentence":"They not only washed off the sweat, dirt and cares of the day in the hot water, but also enjoyed gossiping about everyday affairs.","translation":"他们不只是洗去汗水、污垢和镇日的操劳，同时也沉浸在闲话家常日常生活当中。","targetForm":"dirt","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dim":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"暗淡的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"模糊的"}],"examples":[{"sentence":"The company decided to dim the office lights after hours, thereby reducing energy consumption without affecting daytime productivity.","translation":"公司决定在下班后调暗办公室灯光，从而在不影响白天生产力的情况下减少能源消耗。","targetForm":"dim","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the dim lighting in the library created a calm atmosphere, it made reading small print difficult for many students.","translation":"尽管图书馆昏暗的灯光营造了宁静的氛围，但让许多学生难以阅读小字。","targetForm":"dim","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"While the old photograph was dim and faded, it still evoked a strong sense of nostalgia among the family members.","translation":"虽然那张旧照片暗淡褪色，但它仍然在家庭成员中唤起强烈的怀旧之情。","targetForm":"dim","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the memory of that distant summer had grown dim over the years, she could only recall fragments of the conversation.","translation":"由于那个遥远夏日的记忆多年来已变得模糊，她只能回忆起对话的片段。","targetForm":"dim","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"If the projector bulb becomes too dim, the audience will struggle to see the presentation, which could undermine the speaker's message.","translation":"如果投影仪灯泡变得太暗，观众将难以看清演示内容，这可能会削弱演讲者的信息传达。","targetForm":"dim","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"diligent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"勤勉的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"用功的"}],"examples":[{"sentence":"The diligent researcher kept detailed notes so that each decision in the experiment could be reviewed later.","translation":"这位勤勉的研究人员保留了详细笔记，以便日后复查实验中的每项决定。","targetForm":"diligent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the archive was difficult to search, the diligent student compared every version of the original letter.","translation":"尽管档案难以检索，这名勤奋学生仍比较了原信件的每个版本。","targetForm":"diligent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"A diligent approach to revision includes testing what has been learned rather than merely reading notes again.","translation":"勤勉的复习方法包括测试所学内容，而不是仅仅再读一遍笔记。","targetForm":"diligent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the team was diligent about checking sources, its final report avoided several common factual errors.","translation":"由于团队认真核查来源，最终报告避免了几项常见事实错误。","targetForm":"diligent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The supervisor praised her diligent preparation, which allowed the meeting to focus on the most difficult questions.","translation":"主管表扬她准备勤奋周全，使会议能够集中讨论最困难的问题。","targetForm":"diligent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"disable":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使失去能力"}],"examples":[{"sentence":"Because the software update may disable legacy features, users are advised to back up their data beforehand.","translation":"由于软件更新可能会禁用旧功能，建议用户事先备份数据。","targetForm":"disable","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The new policy will disable automatic renewal for subscriptions, which gives consumers more control over their expenses.","translation":"新政策将禁用订阅的自动续订，这让消费者对自己的支出有了更多控制。","targetForm":"disable","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"If a virus infects the system, it could disable critical security protocols, leaving sensitive data vulnerable.","translation":"如果病毒感染系统，它可能会禁用关键的安全协议，使敏感数据易受攻击。","targetForm":"disable","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A severe stroke can disable a person's motor functions, thereby requiring long-term rehabilitation and care.","translation":"严重的中风可能使人丧失运动功能，从而需要长期的康复和护理。","targetForm":"disable","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To ensure network security, administrators must disable unused ports that could be exploited by attackers.","translation":"为了确保网络安全，管理员必须禁用可能被攻击者利用的未使用端口。","targetForm":"disable","senseId":"source-v-1","sourceSenseId":"v-1"}]},"diet":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"日常饮食"}],"examples":[{"sentence":"We are going to eat a lot tonight so I hope that you are not on a diet.","translation":"我们今晚会吃很多，所以我希望你没有在节食。","targetForm":"diet","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She is on a diet for fear that she will put on weight.","translation":"她因为担心发胖而节食。","targetForm":"diet","senseId":"source-n-1","sourceSenseId":"n-1"}]},"dish":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"盘子"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"菜肴"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"皿；培养皿","contextReviewed":true}],"examples":[{"sentence":"The volunteers placed a dish beneath each sample so that water from the plants would not damage the table.","translation":"志愿者在每个样本下面放了一个盘子，以免植物滴下的水损坏桌面。","targetForm":"dish","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the dish was plain, its hand-painted edge revealed that it had been made by a local craft workshop.","translation":"尽管这个盘子很朴素，它的手绘边缘仍显示它出自当地手工作坊。","targetForm":"dish","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The restaurant introduced a seasonal dish that combined local vegetables with a sauce prepared from fermented beans.","translation":"这家餐厅推出了一道时令菜肴，把本地蔬菜与发酵豆制成的酱汁结合起来。","targetForm":"dish","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Before serving the main dish, the chef explained why the ingredients had been sourced from nearby farms.","translation":"上主菜前，厨师解释了为什么食材来自附近农场。","targetForm":"dish","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The biology class labelled each dish carefully before placing the prepared samples inside the controlled cabinet.","translation":"生物课在把制备好的样本放入受控柜之前，仔细给每个培养皿贴上标签。","targetForm":"dish","senseId":"source-n-4","sourceSenseId":"n-4"}]},"discern":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"了解"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"辨别"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"看清楚"}],"examples":[{"sentence":"Effective leaders discern the underlying concerns of their team members even when those concerns are not explicitly voiced.","translation":"高效的领导者即使团队成员没有明确表达，也能了解他们潜在的担忧。","targetForm":"discern","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Experienced teachers can quickly discern which students need extra support by observing subtle changes in their classroom behavior.","translation":"经验丰富的教师通过观察学生课堂行为的细微变化，能迅速辨别哪些学生需要额外帮助。","targetForm":"discern","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To make informed investment decisions, analysts must discern genuine market trends from short-term fluctuations that are driven by speculation.","translation":"为了做出明智的投资决策，分析师必须从投机驱动的短期波动中辨别出真正的市场趋势。","targetForm":"discern","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the two research proposals appeared similar at first glance, the review committee was able to discern significant methodological differences upon closer examination.","translation":"尽管这两份研究计划乍看相似，但评审委员会经过仔细审查后，能够辨别出方法上的显着差异。","targetForm":"discern","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the ancient manuscript was badly faded, scholars used multispectral imaging to discern the original text that had been invisible to the naked eye.","translation":"由于这份古代手稿褪色严重，学者们利用多光谱成像来辨别肉眼无法看到的原始文本。","targetForm":"discern","senseId":"source-v-2","sourceSenseId":"v-2"}]},"discharge":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"放出"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"履行"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"放电"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"解雇"}],"examples":[{"sentence":"Companies that discharge untreated industrial waste into rivers face severe penalties under the newly revised environmental protection law.","translation":"根据新修订的环境保护法，将未经处理的工业废水排入河流的企业将面临严厉处罚。","targetForm":"discharge","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The hospital decided to discharge the patient after confirming that his vital signs had remained stable for two consecutive days.","translation":"医院在确认病人生命体征连续两天保持稳定后，决定让他出院。","targetForm":"discharge","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"To discharge her responsibility as a mentor, she regularly held workshops that helped junior researchers refine their academic writing skills.","translation":"为履行作为导师的职责，她定期举办研讨会，帮助初级研究人员提升学术写作能力。","targetForm":"discharge","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The battery can discharge its stored energy within minutes when connected to a high-power device, which makes it suitable for emergency backup systems.","translation":"当连接到高功率设备时，电池能在几分钟内释放其储存的能量，这使其适用于应急备用系统。","targetForm":"discharge","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"Although he had served the organization faithfully for over a decade, the board voted to discharge him due to repeated violations of the code of conduct.","translation":"尽管他已为组织忠诚服务了十多年，董事会仍因他屡次违反行为准则而投票决定解雇他。","targetForm":"discharge","senseId":"source-v-3","sourceSenseId":"v-3"}]},"distract":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"转移"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"分心"}],"examples":[{"sentence":"As US Federal Reserve Chairman Ben Bernanke has argued, trade expansion inevitably creates some losers, whose protests distract attention from the benefits of globalization.","translation":"这个观点是正确的，但是，它只是事情的一部分，因为它忽略了在关键时刻，自由贸易是怎样获得众多胜利者的支持的。","targetForm":"distract","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Meanwhile, Jiang Qin distracted Jiang Feng's older brother Yan Daxia.","translation":"与此同时江琴分散了江枫的哥哥燕大侠的注意力。","targetForm":"distracted","senseId":"source-v-2","sourceSenseId":"v-2"}]},"digital":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"数字的"}],"examples":[{"sentence":"It is not difficult to see why an authoritarian regime would want to prevent its people from having access to potentially untraceable, secure digital records.","translation":"不难看出为何极权体制想要阻止人民接触有可能不可追踪的安全的数字记录。","targetForm":"digital","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"That year's buzzword was digital: digital clocks, digital microwave ovens, even digital pens.","translation":"那一年的流行语是「数位」：数位钟、数位微波炉，甚至还有数位笔。","targetForm":"digital","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"ditch":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"沟渠"}],"examples":[{"sentence":"Tom was driving too fast on the bend and ended up in the ditch.","translation":"汤姆拐弯儿拐得太快了，把车开到了水沟里。","targetForm":"ditch","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom took the bend too fast and landed in the ditch.","translation":"汤姆拐弯儿拐得太快了，把车开到了水沟里。","targetForm":"ditch","senseId":"source-n-1","sourceSenseId":"n-1"}]},"discreet":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"慎重的"}],"examples":[{"sentence":"Mary told me that she thought Tom would be discreet.","translation":"玛丽跟我说他觉得汤姆很谨慎。","targetForm":"discreet","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"dispute":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"争论"}],"examples":[{"sentence":"Thus, while the Likud referendum seems to have left the Israeli-Palestinian dispute at yet another impasse, both sides are on the verge of enormous changes.","translation":"因此，虽然利库德的全党公决似乎使以巴争端陷入了另一个僵局，但双方的政局都处在巨变的边缘。","targetForm":"dispute","senseId":"source-n-1","sourceSenseId":"n-1"}]},"disturb":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使不安"}],"examples":[{"sentence":"All of these events have disturbed and disoriented Turkey, and are magnified by the domestic impact of worst global economic crisis since the 1930’s.","translation":"所有这些事件都让土耳其感到不安和无所适从，这些事件并因20世纪30年代以来最严重的全球性经济危机对国内的影响而被放大。","targetForm":"disturbed","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"BAGHDAD – Europe’s migration debate has taken a disturbing turn.","translation":"巴格达—欧洲的移民争论正在发生令人不安的转折。","targetForm":"disturbing","senseId":"source-v-3","sourceSenseId":"v-3"}]},"disorder":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"混乱"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"扰乱"}],"examples":[{"sentence":"The office fell into disorder after several boxes of unsorted records arrived on the same day.","translation":"几箱未分类记录同一天到达后，办公室陷入混乱。","targetForm":"disorder","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A sudden change in the schedule can disorder a carefully planned sequence of interviews.","translation":"时间表突然改变会扰乱精心安排的一系列访谈。","targetForm":"disorder","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The volunteers ended the disorder after the storm had scattered signs and equipment across the field.","translation":"风暴把标志和设备吹散到田野各处后，志愿者结束了混乱。","targetForm":"disorder","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Noise from the construction work disordered the recording, so the team repeated the interview indoors.","translation":"施工噪音扰乱了录音，因此团队在室内重做访谈。","targetForm":"disordered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The guide explains how small errors in filing can create disorder in a large archive.","translation":"指南解释了归档中的小错误如何在大型档案中造成混乱。","targetForm":"disorder","senseId":"source-n-2","sourceSenseId":"n-2"}]},"diploma":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"文凭"}],"examples":[{"sentence":"She received her diploma after completing the final project and all required practical training.","translation":"完成最终项目和所有规定实践培训后，她获得了文凭。","targetForm":"diploma","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The university issued a replacement diploma when the graduate lost the original during a move.","translation":"毕业生搬家时丢失原件后，大学补发了一份文凭。","targetForm":"diploma","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A diploma can show that a student has completed a course, but it does not replace experience.","translation":"文凭能表明学生完成了课程，但不能替代经验。","targetForm":"diploma","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The school displayed diplomas from its earliest graduates in a case near the entrance.","translation":"学校在入口附近的展柜中展示了最早一批毕业生的文凭。","targetForm":"diplomas","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Before applying for work abroad, he asked how to have his diploma officially translated.","translation":"申请海外工作前，他询问如何将文凭进行官方翻译。","targetForm":"diploma","senseId":"source-n-1","sourceSenseId":"n-1"}]},"diminish":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"(使)减少"}],"examples":[{"sentence":"Maastricht treaty or no Maastricht treaty, loss of public support for the ECB will diminish its independence.","translation":"无论是否有马斯特里赫特条约，丧失公众对欧洲央行的支持将会削弱其独立性。","targetForm":"diminish","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A great Empire, like a great Cake, is most easily diminished at the Edges.","translation":"一个伟大的帝国, 就像是一个大蛋糕, 最容易消失的地方就在边缘。","targetForm":"diminished","senseId":"source-v-1","sourceSenseId":"v-1"}]},"dine":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"用正餐"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"进餐"}],"examples":[{"sentence":"Even if they have a good wine menu, I will not want to dine here.","translation":"即使他们有很好的酒单，我也不想在这里用餐。","targetForm":"dine","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"At around 12pm, we go to the dining area of our unit for lunch.","translation":"中午十二点左右，到我们单位的饭厅去吃午饭。","targetForm":"dining","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"It's too bad the college dining hall doesn't have fig cookies.","translation":"可惜大学食堂没有无花果饼干。","targetForm":"dining","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Sorry, I was dining and I didn't see the message.","translation":"抱歉，我刚才在吃饭，没有看到信息。","targetForm":"dining","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The living room is right next to the dining room.","translation":"客厅紧邻着餐厅。","targetForm":"dining","senseId":"source-v-2","sourceSenseId":"v-2"}]},"discount":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"折扣"}],"examples":[{"sentence":"For quantities of 20 or more, we can allow you a special discount of 10% on the prices quoted.","translation":"20个以上九折特惠。","targetForm":"discount","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Your initial order is subject to a special discount of 5%.","translation":"首次订购可获九五折的特别优惠。","targetForm":"discount","senseId":"source-n-1","sourceSenseId":"n-1"}]},"distant":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"远的"}],"examples":[{"sentence":"Today we can go to distant countries easily by plane.","translation":"现在我们很容易就能乘飞机去遥远的国度。","targetForm":"distant","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"divide":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"分裂"}],"examples":[{"sentence":"But, behind all the smiles and banquet toasts, serious issues and perception gaps continue to divide the world’s two great powers.","translation":"但在宾主笑脸相迎，推杯换盏的背后依然存在着一系列严重问题以及理念差距，不断撕裂着两个世界大国之间的关系。","targetForm":"divide","senseId":"source-v-3","sourceSenseId":"v-3"}]},"discuss":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"讨论"}],"examples":[{"sentence":"The broad range of issues to be discussed mirrors the essential place of the Alliance in addressing today’s security challenges.","translation":"这些即将被讨论的议题范围之广反映了北约在面对当今安全挑战中的重要地位。","targetForm":"discussed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"I can't calculate the final cost without first discussing it with our contractors.","translation":"不先与我们的承包商讨论的话我无法计算出最后的费用。","targetForm":"discussing","senseId":"source-v-1","sourceSenseId":"v-1"}]},"disappear":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"消失"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"不见"}],"examples":[{"sentence":"The truth is that trafficking will stop only when the need for organs disappears.","translation":"事实是：只有不需要器官的时候，走私才能停止。","targetForm":"disappears","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Earlier, in 1995, China installed its own Panchen Lama after its security services abducted the Tibetans’ six-year-old appointee, who has simply disappeared, along with his family.","translation":"在更早之前的1995年，中国国家安全机关在劫持了藏人选定的6岁班禅喇嘛继任人及其全家之后拥立了自己的班禅喇嘛。","targetForm":"disappeared","senseId":"source-v-2","sourceSenseId":"v-2"}]},"dip":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"浸"}],"examples":[{"sentence":"The tip of the spear was dipped in a deadly poison.","translation":"矛尖浸在一种致命的毒药里。","targetForm":"dipped","senseId":"source-v-1","sourceSenseId":"v-1"}]},"division":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"分开"}],"examples":[{"sentence":"Both examples show that Europe, like the US, is vulnerable to the politics of division, as our societies become more ethnically diverse.","translation":"这两个例子都显示出随着我们的社会在种族上越来越多元化，欧洲也无法克服随之诱发的政治分裂现象，正如美国一样。","targetForm":"division","senseId":"source-n-2","sourceSenseId":"n-2"}]},"display":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"陈列"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"显示"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"陈列"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"表现"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"炫耀"}],"examples":[{"sentence":"The museum created a display that explained how the town changed after the railway arrived.","translation":"博物馆制作了一个展览，解释铁路到来后小镇如何变化。","targetForm":"display","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The screen display shows the room temperature and warns staff when it rises too quickly.","translation":"屏幕显示室温，并在温度上升过快时警告员工。","targetForm":"display","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Students displayed their maps along the corridor before explaining their research to visitors.","translation":"学生在向访客解释研究前，沿走廊展示了地图。","targetForm":"displayed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The child displayed patience by waiting until the librarian had finished helping another reader.","translation":"孩子耐心等待图书管理员帮助完另一位读者，表现出耐心。","targetForm":"displayed","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The report treats the figures as evidence, not as a display of technical skill for its own sake.","translation":"报告把这些数字视为证据，而不是为炫耀技术而作的展示。","targetForm":"display","senseId":"source-n-3","sourceSenseId":"n-3"}]},"discover":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"发现"}],"examples":[{"sentence":"When we started, we thought that we knew everything, but we later discovered that we did not.","translation":"开始的时候，我们以为我们什么都知道，但后来发现，事实是我们什么都不知道。","targetForm":"discovered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Columbus's Law of Discovery states: If you discovered something BEFORE Christopher Columbus, then what you discovered does not exist.","translation":"哥伦布的发现新大陆法则：如果你在克里斯多福·哥伦布之前发现了某个东西，那么你所发现的是不存在的。","targetForm":"discovered","senseId":"source-v-1","sourceSenseId":"v-1"}]},"difference":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"不同"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"差异"}],"examples":[{"sentence":"The good news is that there are three relatively simple interventions that could make a big difference.","translation":"好消息是有三种相对简单的干预方法能够带来巨大的不同。","targetForm":"difference","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There are three differences between the euro and the gold standard – none of which is particularly reassuring at this moment.","translation":"欧元制和金本位制有三个不同点，可是现在，没有一点能让人从中得到安慰。","targetForm":"differences","senseId":"source-n-2","sourceSenseId":"n-2"}]}}};
